def choose_move(observation):
    o = observation if isinstance(observation, dict) else {}

    def pt(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return default
        if isinstance(v, dict):
            try:
                return int(v.get("x", default[0])), int(v.get("y", default[1]))
            except Exception:
                return default
        return default

    def clamp_step(a):
        return -1 if a < 0 else (1 if a > 0 else 0)

    w = int(o.get("grid_width", o.get("width", 0)) or 0)
    h = int(o.get("grid_height", o.get("height", 0)) or 0)

    sx, sy = pt(o.get("self_position", o.get("agent_position", (0, 0))))
    ox, oy = pt(o.get("opponent_position", o.get("enemy_position", (sx, sy))))

    resources = o.get("resources", o.get("resource_positions", [])) or []
    obstacles = o.get("obstacles", o.get("walls", [])) or []
    blocked = set()
    for p in obstacles:
        x, y = pt(p, None) if p is not None else None
        if x is not None:
            blocked.add((x, y))

    def legal(a, b):
        nx, ny = sx + a, sy + b
        if (w > 0 and not (0 <= nx < w)) or (h > 0 and not (0 <= ny < h)):
            return False
        return (nx, ny) not in blocked

    def dist(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    # Resource target
    target = None
    best = None
    for p in resources:
        x, y = pt(p, None) if p is not None else None
        if x is None:
            continue
        d = dist(sx, sy, x, y)
        if best is None or d < best or (d == best and (x, y) < target):
            best = d
            target = (x, y)

